3. **Increment the `numTurns` field** every time a second card is flipped.
4. **Update the label** to show both the number of turns and the number of matches.

Below is the modified `GamePane.java` file:

```java
package com.example.javamemorygame;

import javafx.animation.FadeTransition;
import javafx.animation.TranslateTransition;
import javafx.application.Platform;
import javafx.beans.value.ChangeListener;
import javafx.beans.value.ObservableValue;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.control.Alert;
import javafx.scene.control.Alert.AlertType;
import javafx.scene.control.ButtonType;
import javafx.scene.control.Label;
import javafx.scene.control.ListView;
import javafx.scene.layout.Background;
import javafx.scene.layout.BackgroundFill;
import javafx.scene.layout.CornerRadii;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.StackPane;
import javafx.scene.layout.VBox;
import javafx.scene.paint.Color;
import javafx.scene.shape.Rectangle;
import javafx.scene.text.Font;
import javafx.scene.text.FontWeight;
import javafx.util.Duration;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Optional;

public class GamePane extends StackPane {
    private int[] cards;
    private int[] revealed;
    private int numClicks = 0;
    private int numMatched = 0;
    private int numTurns = 0; // New field to track the number of turns

    private List<Integer> cardValues;
    private GridPane gridPane;
    private Label statusLabel;
    private ListView<String> levelListView;
    private Button newGameButton;

    public GamePane() {
        this(8); // Default card size
    }

    public GamePane(int cardSize) {
        this.cardSize = cardSize;

        // Initialize cards and revealed arrays
        cards = new int[cardSize * cardSize];
        revealed = new int[cardSize * cardSize];

        // Initialize card values
        cardValues = new ArrayList<>();
        for (int i = 0; i < cardSize * cardSize / 2; i++) {
            cardValues.add(i);
            cardValues.add(i);
        }
        Collections.shuffle(cardValues);

        // Initialize grid pane
        gridPane = new GridPane();
        gridPane.setPadding(new Insets(10));
        gridPane.setHgap(10);
        gridPane.setVgap(10);

        // Initialize status label
        statusLabel = new Label("turns: 0 | matches: 0");
        statusLabel.setFont(Font.font("Arial", FontWeight.BOLD, 16));

        // Initialize level list view
        levelListView = new ListView<>();
        levelListView.getItems().addAll("Level 1", "Level 2", "Level 3");
        levelListView.getSelectionModel().selectedItemProperty().addListener(new ChangeListener<String>() {
            @Override
            public void changed(ObservableValue<? extends String> observable, String oldValue, String newValue) {
                startNewGame();
            }
        });

        // Initialize new game button
        newGameButton = new Button("New Game");
        newGameButton.setOnAction(e -> startNewGame());

        // Initialize HBox for controls
        HBox controlBox = new HBox(10);
        controlBox.setAlignment(Pos.CENTER);
        controlBox.getChildren().addAll(levelListView, newGameButton);

        // Initialize VBox for layout
        VBox vbox = new VBox(10);
        vbox.setAlignment(Pos.CENTER);
        vbox.getChildren().addAll(statusLabel, controlBox, gridPane);

        // Add components to the stack pane
        getChildren().add(vbox);

        // Initialize cards
        for (int i = 0; i < cardSize * cardSize; i++) {
            Rectangle card = new Rectangle(100, 150, Color.LIGHTGRAY);
            card.setOnMouseClicked(e -> flipCard(i));
            gridPane.add(card, i % cardSize, i / cardSize);
        }

        // Initialize the game
        startNewGame();
    }

    private void startNewGame() {
        numClicks = 0;
        numMatched = 0;
        numTurns = 0; // Reset the turn counter
        statusLabel.setText("turns: 0 | matches: 0");

        // Reinitialize cards and revealed arrays
        for (int i = 0; i < cards.length; i++) {
            cards[i] = cardValues.get(i);
            revealed[i] = 0;
        }

        // Reinitialize grid pane
        for (int i = 0; i < gridPane.getChildren().size(); i++) {
            GridPane.setRowIndex(gridPane.getChildren().get(i), i / 8);
            GridPane.setColumnIndex(gridPane.getChildren().get(i), i % 8);
        }

        // Reset the status label
        updateStatusLabel();
    }

    private void flipCard(int index) {
