### JavaScript (inline `<script>` block in `projects.html`)

Next, add the JavaScript code to handle the search functionality:

```html
<script>
document.addEventListener('DOMContentLoaded', function() {
    const filterButtons = document.querySelectorAll('.filter-btn');
    const searchBox = document.getElementById('search-box');
    const cardWraps = document.querySelectorAll('.card-wrap');

    // Function to show all cards initially
    function showAllCards() {
        cardWraps.forEach(card => card.style.display = '');
    }

    // Function to apply filter
    function applyFilter() {
        const selectedTag = document.querySelector('.filter-btn.active').getAttribute('data-tag');
        const searchText = searchBox.value.toLowerCase().trim();

        cardWraps.forEach(card => {
            const cardTags = card.getAttribute('data-tags').toLowerCase().split(' ');
            const cardName = card.querySelector('.card-name').innerText.toLowerCase();
            const cardStack = card.querySelector('.card-stack').innerText.toLowerCase();

            if ((selectedTag === 'all' || cardTags.includes(selectedTag)) && 
                (searchText === '' || cardName.includes(searchText) || cardStack.includes(searchText))) {
                card.style.display = '';
            } else {
                card.style.display = 'none';
            }
        });
    }

    // Event listener for filter buttons
    filterButtons.forEach(button => {
        button.addEventListener('click', function() {
            document.querySelector('.filter-btn.active').classList.remove('active');
            this.classList.add('active');
            applyFilter();
        });
    });

    // Event listener for search box
    searchBox.addEventListener('input', function() {
        applyFilter();
    });

    // Initially show all cards
    showAllCards();
});
</script>
```

### Explanation

1. **HTML Update**:
   - Added a search box inside the filter bar container with the ID `search-box`.

