```jsx
import React, { useState } from 'react';

export default function LotSelector({ lots, selectedLot, onSelect }) {
    const [favoriteLots, setFavoriteLots] = useState(() => {
        const storedFavorites = localStorage.getItem('favoriteLots');
        return storedFavorites ? JSON.parse(storedFavorites) : [];
    });

    const toggleFavorite = (lotID) => {
        if (favoriteLots.includes(lotID)) {
            setFavoriteLots(favoriteLots.filter(id => id !== lotID));
        } else {
            setFavoriteLots([...favoriteLots, lotID]);
        }
    };

    useEffect(() => {
        localStorage.setItem('favoriteLots', JSON.stringify(favoriteLots));
    }, [favoriteLots]);

    const isFavorite = (lotID) => favoriteLots.includes(lotID);

    return (
        <div className="p-4 bg-white shadow">
            <div className="flex items-center gap-2 mb-3">
                <svg className="text-green-700" width="20" height="20" fill="currentColor" viewBox="0 0 24 24">
                    <path d="[SVG_D_DATA_OMITTED:167_chars]"/>
                </svg>
                <span className="font-semibold text-gray-700">Select Parking Lot</span>
            </div>
            <div className="flex gap-2 overflow-x-auto pb-2">
                {lots.sort((a, b) => {
                    if (isFavorite(b.Lot_ID) && !isFavorite(a.Lot_ID)) return -1;
                    if (!isFavorite(b.Lot_ID) && isFavorite(a.Lot_ID)) return 1;
                    return 0;
                }).map(lot => (
                    <button
                        key={lot.Lot_ID}
                        onClick={() => onSelect(lot.Lot_ID)}
                        className={`px-4 py-2 rounded-lg whitespace-nowrap transition flex-shrink-0 ${
