                                ? 'bg-green-700 text-white shadow-md'
                                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                        }`}
                    >
                        <div className="font-semibold">{lot.Lot_Name}</div>
                        <div className="text-xs">{lot.Num_Spaces} open</div>
